import {C,rect,text,line,arrow,clamp} from './svg.js';import {layout} from './layout.js';
function mix(q){return`rgb(${Math.round(159+52*q)},${Math.round(197-38*q)},${Math.round(217-75*q)})`;}
export function draw(s,size){const{w,h,mobile,f,L,R,top,y,xl,xr}=layout(size),span=R-L,bw=xr-xl,hxa=L+span*.43,hxb=L+span*.70,pumpY=(top+y)/2;let out=`<defs><linearGradient id="water-channel" gradientUnits="userSpaceOnUse" x1="${xl}" x2="${xr}"><stop offset="0" stop-color="#9FC5D9"/><stop offset="1" stop-color="#D39F8E"/></linearGradient><linearGradient id="water-exchanger" gradientUnits="userSpaceOnUse" x1="${hxa}" x2="${hxb}"><stop offset="0" stop-color="#9FC5D9"/><stop offset="1" stop-color="#D39F8E"/></linearGradient></defs>`+text(w/2,25,s.caption,f,C.muted);
out+=rect(hxa-6,top-16,hxb-hxa+12,32,C.tool);for(let i=0;i<6;i++){const px=hxa+(hxb-hxa)*i/5;out+=line(px,top-23,px,top+23,C.line,1.4);}out+=text((hxa+hxb)/2,top-32,'換熱器 → 環境',f);
const route=`M${L} ${y}H${R}V${top}H${L}Z`;out+=`<path d="${route}" stroke="${C.line}" stroke-width="20" stroke-linejoin="round" fill="none"/>`;out+=line(L,y,xl,y,C.water,16)+line(xr,y,R,y,'#D39F8E',16)+line(R,y,R,top,'#D39F8E',16)+line(R,top,hxb,top,'#D39F8E',16)+line(hxa,top,L,top,C.water,16)+line(L,top,L,y,C.water,16)+line(hxa,top,hxb,top,'url(#water-exchanger)',16);
out+=rect(xl,y-26,bw,48,C.silicon,'data-material="silicon-cooler"')+rect(xl,y-8,bw,16,'url(#water-channel)','stroke="none"')+rect(xl,y+22,bw,6,C.purple,'data-material="ag-epoxy"')+rect(xl,y+28,bw,22,'#D9AE9E','data-material="chip"');
out+=text(w/2,y-12,'矽微流道冷卻器',14)+text(w/2,y+44,'持續發熱晶片',f);for(let i=1;i<6;i++)out+=rect(xl+bw*i/6-4,y+50,8,5,C.copper);
out+=text(w/2,y+76,'薄紫層：銀填充環氧',mobile?13:15,C.muted);
out+=`<g opacity="${s.pulse}">`;for(const pos of[.21,.79])out+=arrow(xl+bw*pos,y+43,xl+bw*pos,y+2,C.heat,2.4);for(const pos of[.25,.75])out+=arrow(hxa+(hxb-hxa)*pos,top-17,hxa+(hxb-hxa)*pos,top-26,C.heat,2);out+='</g>';
out+=`<circle cx="${L}" cy="${pumpY}" r="16" fill="${C.tool}" stroke="${C.line}" stroke-width="1.5"/>`+arrow(L,pumpY-8,L,pumpY+8,'#477F9E',2)+text(L+23,pumpY+5,'泵',f,C.ink,'start');
out+=arrow(xl+bw*.26,y,xl+bw*.40,y,'#477F9E',1.6)+arrow(xl+bw*.59,y,xl+bw*.73,y,'#477F9E',1.6)+arrow(R,y-15,R,top+20,'#477F9E',1.6)+arrow(hxa-15,top,L+24,top,'#477F9E',1.6);
out+=text(L+15,y+29,'較冷',13,C.muted)+text(L+15,y+44,'入口',13,C.muted)+text(R-15,y+29,'較暖',13,C.muted)+text(R-15,y+44,'出口',13,C.muted);
const len=2*(span+y-top);function at(p){let z=((p%1)+1)%1*len;if(z<span){const x=L+z;return{x,y,temp:clamp((x-xl)/bw)};}z-=span;if(z<y-top)return{x:R,y:y-z,temp:1};z-=y-top;if(z<span){const x=R-z;return{x,y:top,temp:clamp((x-hxa)/(hxb-hxa))};}z-=span;return{x:L,y:top+z,temp:0};}
const parcel=at(s.phase),pa=at(s.phase-5/len),pb=at(s.phase+5/len);out+=`<path data-fluid-parcel="same-parcel" d="M${pa.x} ${pa.y}L${parcel.x} ${parcel.y}L${pb.x} ${pb.y}" fill="none" stroke="#8A713A" stroke-width="9" stroke-linecap="round"/>`+`<path d="M${pa.x} ${pa.y}L${parcel.x} ${parcel.y}L${pb.x} ${pb.y}" fill="none" stroke="${mix(parcel.temp)}" stroke-width="5" stroke-linecap="round"/>`;
if(s.index===0)out+=rect(xl-4,y+18,bw+8,41,'none','stroke="#BE9C69" stroke-dasharray="3 4"');if(s.index===1)out+=rect(xl-4,y-13,bw+8,26,'none','stroke="#BE9C69" stroke-dasharray="3 4"');if(s.index===2)out+=line(R+14,y-4,R+14,top,'#BE9C69',1.5,'stroke-dasharray="3 4"');if(s.index===3)out+=rect(hxa-10,top-27,hxb-hxa+20,54,'none','stroke="#BE9C69" stroke-dasharray="3 4"');
out+=text(w/2,h-12,mobile?'橙：熱流 · 藍：流向 · 金框：同一流體段':'橙色箭頭：熱流　藍色箭頭：流向　金框短段：同一示意流體',mobile?12:15,C.muted);return out;}
